import { Component, OnInit } from '@angular/core';
import { MarcheService } from '../../services/marche.service';
@Component({ selector: 'app-dashboard', templateUrl: './dashboard.component.html', styleUrls: ['./dashboard.component.scss'] })
export class DashboardComponent implements OnInit {
  totalMarches = 0; actifCount = 0; enAttenteCount = 0; archiveCount = 0; recentMarches: any[] = [];
  constructor(private marcheService: MarcheService) {}
  ngOnInit() { this.loadData(); }
  loadData() {
    this.marcheService.getAllMarches().subscribe({
      next: (marches) => {
        this.totalMarches = marches.length;
        this.actifCount = marches.filter((m:any) => m.statut === 'ACTIF').length;
        this.enAttenteCount = marches.filter((m:any) => m.statut === 'EN_ATTENTE').length;
        this.archiveCount = marches.filter((m:any) => m.statut === 'ARCHIVE').length;
        this.recentMarches = marches.slice(0, 5);
      },
      error: (error) => console.error(error)
    });
  }
}
<div class="dashboard">
  <h2>📊 Tableau de bord</h2>
  <div class="stats-grid">
    <div class="stat-card"><div class="stat-number">{{ totalMarches }}</div><div class="stat-label">📦 Total</div></div>
    <div class="stat-card" style="border-left-color:#28a745;"><div class="stat-number">{{ actifCount }}</div><div class="stat-label">✅ Actifs</div></div>
    <div class="stat-card" style="border-left-color:#ffc107;"><div class="stat-number">{{ enAttenteCount }}</div><div class="stat-label">⏳ En attente</div></div>
    <div class="stat-card" style="border-left-color:#6c757d;"><div class="stat-number">{{ archiveCount }}</div><div class="stat-label">📁 Archivés</div></div>
  </div>
  <div class="recent-marches" *ngIf="recentMarches.length > 0">
    <h3>📋 Derniers marchés</h3>
    <ul>
      <li *ngFor="let marche of recentMarches">
        <span class="ref">{{ marche.reference }}</span>
        <span class="title">{{ marche.objet }}</span>
        <span class="badge" [class.badge-success]="marche.statut === 'ACTIF'" [class.badge-warning]="marche.statut === 'EN_ATTENTE'" [class.badge-secondary]="marche.statut === 'ARCHIVE'">{{ marche.statut }}</span>
      </li>
    </ul>
  </div>
</div>
